import type { SettingDefinition } from '$types/sections/settings'

type Required = Pick<SettingDefinition, 'key' | 'type' | 'label' | 'group'>
const definition = (fields: Required & Partial<SettingDefinition>): SettingDefinition => ({
  env: `KNIK_${fields.key.toUpperCase()}`,
  default: null,
  description: '',
  options: null,
  secret: false,
  nullable: false,
  minimum: null,
  maximum: null,
  value: null,
  source: 'default',
  ...fields,
})

/** A backend schema the way GET /api/admin/settings lists it: three groups, every control type, stored keys. */
export const remoteSettings: SettingDefinition[] = [
  definition({
    key: 'display_name',
    type: 'str',
    label: 'Display name',
    group: 'Profile',
    nullable: true,
    value: 'Alex',
  }),
  definition({
    key: 'ai_provider',
    type: 'str',
    label: 'Provider',
    group: 'AI',
    options: ['vertex', 'mock'],
    value: 'vertex',
    default: 'vertex',
    source: 'env',
  }),
  definition({
    key: 'ai_model',
    type: 'str',
    label: 'Model',
    group: 'AI',
    nullable: true,
    value: 'gemini-1.5-flash',
    source: 'db',
  }),
  definition({
    key: 'temperature',
    type: 'float',
    label: 'Temperature',
    group: 'AI',
    minimum: 0,
    maximum: 2,
    value: 0.7,
    default: 0.7,
  }),
  definition({
    key: 'max_tokens',
    type: 'int',
    label: 'Max output tokens',
    group: 'AI',
    description: "Empty leaves the provider's own limit.",
    nullable: true,
    minimum: 1,
    value: 1024,
    source: 'db',
  }),
  definition({
    key: 'custom_api_key',
    type: 'str',
    label: 'Custom API key',
    group: 'AI',
    secret: true,
    nullable: true,
    value: '••••••',
    source: 'db',
  }),
  definition({
    key: 'voice_name',
    type: 'str',
    label: 'Voice',
    group: 'Voice',
    options: ['af_heart', 'am_adam'],
    value: 'af_heart',
    default: 'af_heart',
  }),
  definition({
    key: 'enable_voice_output',
    type: 'bool',
    label: 'Speak replies',
    group: 'Voice',
    value: true,
    default: true,
  }),
]
